import { setActivePinia } from 'pinia';
import { createScriptIdDiv, teleportStyle } from '@util/script';
import SettingsPanel from './SettingsPanel.vue';
import { useSettingsStore } from './settings';
import { syncStripRegexes } from './regexes';
import { processLatestAI, resetPipelineState } from './pipeline';
$(() => {
    const pinia = createPinia();
    setActivePinia(pinia);
    // 按钮
    appendInexistentScriptButtons([
        { name: '设置', visible: true },
        { name: '重新生成', visible: true },
    ]);
    eventOn(getButtonEvent('设置'), () => {
        const $drawer = $('.postgen-settings .inline-drawer-toggle');
        if ($drawer.length) {
            $drawer.trigger('click');
            $drawer[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
    });
    eventOn(getButtonEvent('重新生成'), () => {
        processLatestAI(true);
    });
    // 设置面板
    const app = createApp(SettingsPanel).use(pinia);
    const $app = createScriptIdDiv().appendTo('#extensions_settings2');
    app.mount($app[0]);
    const { destroy } = teleportStyle();
    // 剥离正则: 相关设置变化时自动同步
    const store = useSettingsStore();
    const regex_signature = computed(() => JSON.stringify([
        store.settings.enabled,
        store.settings.strip_regex,
        store.settings.tasks.filter(t => t.enabled).map(t => t.tag),
    ]));
    let regex_timer;
    watch(regex_signature, () => {
        if (regex_timer !== undefined) {
            clearTimeout(regex_timer);
        }
        regex_timer = window.setTimeout(() => {
            regex_timer = undefined;
            syncStripRegexes();
        }, 300);
    }, { immediate: true });
    // 消息事件
    let debounce_timer;
    eventOn(tavern_events.MESSAGE_RECEIVED, () => {
        if (!store.settings.enabled) {
            return;
        }
        if (debounce_timer !== undefined) {
            clearTimeout(debounce_timer);
        }
        debounce_timer = window.setTimeout(() => {
            debounce_timer = undefined;
            processLatestAI(false);
        }, 500);
    });
    // 聊天切换时重载脚本
    eventOn(tavern_events.CHAT_CHANGED, () => {
        resetPipelineState();
    });
    $(window).on('pagehide', () => {
        app.unmount();
        $app.remove();
        destroy();
    });
    console.info('[正文后续生成] 加载完成');
});
