import { uuidv4 } from '@util/common';
export const STATUS_BAR_PROMPT = dedent(`
  你是「状态栏生成器」。根据给定的【正文】和前情提要，提取角色与场景的关键状态（如时间、地点、生命值、体力、情绪、金钱、物品等），生成一段纯文本状态栏。

  要求：
  - 只输出状态栏文本本身，禁止任何其他内容、解释或标记
  - 不超过 50 字
  - 使用「字段: 值」形式，字段之间用「 | 」分隔
  - 状态未变化或未知的字段省略
  - 保持与【上轮任务输出】中该任务内容的连续性，随正文演化
`);
export const OPTIONS_PROMPT = dedent(`
  你是「选项生成器」。根据给定的【正文】和前情提要，生成 3~5 个简短、符合剧情走向的后续动作选项。

  要求：
  - 只输出选项文本本身，禁止任何其他内容、解释或标记
  - 每个选项不超过 15 字，不要编号，不要前缀
  - 选项之间用「|」分隔
  - 选项必须贴合正文中当前局面，是实际可行的下一步
`);
export const TaskSchema = z.object({
    id: z.string().default(() => uuidv4()),
    name: z.string().default('任务'),
    /** 包裹标签名, 生成结果将以 `<tag>...</tag>` 写入楼层 */
    tag: z.string().default('tag'),
    /** 列表式输出的分隔符, 如选项用 `|`; 空表示不分隔 */
    sep: z.string().default(''),
    prompt: z.string().default(''),
    max_tokens: z.number().int().min(16).max(4096).default(256),
    temperature: z.number().min(0).max(2).default(0.7),
    enabled: z.boolean().default(true),
});
export const ApiSchema = z.object({
    /** 自定义 API 地址, 留空则使用酒馆当前连接 */
    apiurl: z.string().default(''),
    apiKey: z.string().default(''),
    /** 留空则使用连接的默认模型 */
    model: z.string().default(''),
    /** 自动识别 / OpenAI Chat Completions / Anthropic Messages */
    source: z.enum(['auto', 'openai', 'claude']).default('auto'),
});
export const SettingsSchema = z
    .object({
    enabled: z.boolean().default(true),
    api: ApiSchema,
    context: z.object({
        /** 提供给辅助请求的前情提要 AI 消息层数 */
        ai_messages: z.number().int().min(0).max(20).default(3),
    }),
    timeout_seconds: z.number().int().min(5).max(300).default(60),
    /** 自动注册酒馆正则, 发送给主 LLM 前剥离任务标签 */
    strip_regex: z.boolean().default(true),
    tasks: z.array(TaskSchema).default(() => defaultTasks()),
})
    .prefault({});
export function defaultTasks() {
    return [
        {
            id: uuidv4(),
            name: '状态栏',
            tag: 'status',
            sep: '',
            prompt: STATUS_BAR_PROMPT,
            max_tokens: 256,
            temperature: 0.5,
            enabled: true,
        },
        {
            id: uuidv4(),
            name: '选项',
            tag: 'options',
            sep: '|',
            prompt: OPTIONS_PROMPT,
            max_tokens: 256,
            temperature: 0.7,
            enabled: true,
        },
    ];
}
export const useSettingsStore = defineStore('postgen_settings', () => {
    const settings = ref(SettingsSchema.parse(getVariables({ type: 'script', script_id: getScriptId() })));
    watchEffect(() => {
        insertOrAssignVariables(klona(settings.value), { type: 'script', script_id: getScriptId() });
    });
    return { settings };
});
