import { uuidv4 } from '@util/common';
import { useSettingsStore } from './settings';

const REGEX_NAME_PREFIX = '正文后续生成-剥离-';

function findRegexForTag(tag: string): string {
  return `<${_.escapeRegExp(tag)}>[\\s\\S]*?</${_.escapeRegExp(tag)}>`;
}

export async function syncStripRegexes(): Promise<void> {
  const store = useSettingsStore();
  const settings = store.settings;
  const enabled = settings.enabled && settings.strip_regex;
  const tags = settings.tasks.filter(t => t.enabled && t.tag).map(t => t.tag);
  try {
    await updateTavernRegexesWith(
      regexes => {
        const ours = regexes.filter(r => String(r.script_name || '').startsWith(REGEX_NAME_PREFIX));
        const others = regexes.filter(r => !String(r.script_name || '').startsWith(REGEX_NAME_PREFIX));
        if (!enabled) {
          return others;
        }
        const existing_names = new Set(ours.map(r => r.script_name));
        const kept: TavernRegex[] = ours.filter(r => tags.includes(String(r.script_name).slice(REGEX_NAME_PREFIX.length)));
        const created: TavernRegex[] = tags
          .filter(tag => !existing_names.has(REGEX_NAME_PREFIX + tag))
          .map(tag => ({
            id: uuidv4(),
            script_name: REGEX_NAME_PREFIX + tag,
            enabled: true,
            find_regex: findRegexForTag(tag),
            replace_string: '',
            trim_strings: [],
            source: { user_input: false, ai_output: true, slash_command: false, world_info: false, reasoning: false },
            destination: { display: false, prompt: true },
            run_on_edit: true,
            min_depth: null,
            max_depth: null,
          }));
        return [...others, ...kept, ...created];
      },
      { type: 'global' },
    );
    console.info(`[正文后续生成] 剥离正则已同步 (${enabled ? tags.length : 0}条)`);
  } catch (error) {
    console.warn('[正文后续生成] 剥离正则同步失败:', error instanceof Error ? error.message : error);
  }
}
