`, "",{"version":3,"sources":["webpack://./src/脚本/正文后续生成/SettingsPanel.vue"],"names":[],"mappings":"AAqLA,mCACE,wBAAyB,CACzB,wBACF,CAEA,gCACE,kBACF,CAEA,kCACE,aAAc,CACd,iBACF,CAEA,gDACE,iBACF,CAEA,+BACE,aAAc,CACd,cAAe,CACf,UAAW,CACX,cACF,CAEA,6BACE,2BACF,CAEA,+BACE,aACF,CAEA,8BACE,UACF,CAEA,iCACE,eACF,CAEA,uCACE,aAAc,CACd,UAAW,CACX,iBACF,CAEA,gCACE,cAAe,CACf,UAAW,CACX,eAAgB,CAChB,kBACF,CAEA,+BACE,uCAA2C,CAC3C,iBAAkB,CAClB,WAAY,CACZ,iBAAkB,CAClB,iCACF,CAEA,iCACE,UAAW,CACX,qBAAsB,CACtB,eAAgB,CAChB,eAAgB,CAChB,mBAAoB,CACpB,cACF,CAEA,iCACE,gBACF","sourcesContent":["<template>\n  <div class=\"postgen-settings\">\n    <div class=\"inline-drawer\">\n      <div class=\"inline-drawer-toggle inline-drawer-header\">\n        <b>正文后续生成</b>\n        <div class=\"inline-drawer-icon fa-solid fa-circle-chevron-down down\"></div>\n      </div>\n      <div class=\"inline-drawer-content\">\n        <div class=\"postgen-block flex-container\">\n          <input id=\"postgen-enable\" v-model=\"settings.enabled\" type=\"checkbox\" />\n          <label for=\"postgen-enable\">启用正文后续生成</label>\n        </div>\n\n        <div class=\"postgen-block\">\n          <b>API 配置（所有任务共用）</b>\n          <div class=\"flex-container\">\n            <input v-model=\"settings.api.apiurl\" type=\"text\" placeholder=\"留空=使用酒馆当前连接\" class=\"text_pole\" />\n          </div>\n          <div class=\"flex-container\">\n            <input v-model=\"settings.api.apiKey\" :type=\"apiKeyVisible ? 'text' : 'password'\" placeholder=\"API Key（可选）\" class=\"text_pole\" />\n            <input type=\"button\" class=\"menu_button\" :value=\"apiKeyVisible ? '隐藏' : '显示'\" @click=\"apiKeyVisible = !apiKeyVisible\" />\n          </div>\n          <div class=\"flex-container\">\n            <input v-model=\"settings.api.model\" type=\"text\" placeholder=\"模型（留空=默认模型）\" class=\"text_pole\" />\n            <input type=\"button\" class=\"menu_button\" :value=\"fetching ? '拉取中…' : '拉取'\" :disabled=\"fetching\" @click=\"fetchModels\" />\n          </div>\n          <select v-if=\"fetchedModels.length\" v-model=\"settings.api.model\" class=\"postgen-model-select\">\n            <option value=\"\">— 选择模型 —</option>\n            <option v-for=\"model in fetchedModels\" :key=\"model\" :value=\"model\">{{ model }}</option>\n          </select>\n          <div class=\"flex-container\">\n            <select v-model=\"settings.api.source\" class=\"postgen-select\">\n              <option value=\"auto\">自动识别（推荐）</option>\n              <option value=\"openai\">OpenAI Chat Completions</option>\n              <option value=\"claude\">Anthropic Messages</option>\n            </select>\n            <input type=\"button\" class=\"menu_button\" :value=\"testing ? '测试中…' : '测试API'\" :disabled=\"testing\" @click=\"testApi\" />\n          </div>\n          <small class=\"postgen-hint\">{{ apiHint }}</small>\n          <small v-if=\"apiTestStatus\" class=\"postgen-hint\" :class=\"apiTestOk ? 'postgen-ok' : 'postgen-warn'\">{{ apiTestStatus }}</small>\n        </div>\n\n        <div class=\"postgen-block\">\n          <b>生成配置</b>\n          <div class=\"flex-container\">\n            <input v-model.number=\"settings.context.ai_messages\" type=\"number\" min=\"0\" max=\"20\" class=\"postgen-num\" />\n            <label class=\"postgen-label\">前情提要 AI 消息层数</label>\n          </div>\n          <div class=\"flex-container\">\n            <input v-model.number=\"settings.timeout_seconds\" type=\"number\" min=\"5\" max=\"300\" class=\"postgen-num\" />\n            <label class=\"postgen-label\">超时秒数</label>\n          </div>\n          <div class=\"flex-container\">\n            <input id=\"postgen-strip\" v-model=\"settings.strip_regex\" type=\"checkbox\" />\n            <label for=\"postgen-strip\">发送给主 LLM 前剥离任务标签（自动注册酒馆正则）</label>\n          </div>\n        </div>\n\n        <div class=\"postgen-block\">\n          <div class=\"flex-container\" style=\"justify-content: space-between\">\n            <b>任务列表（正文后续的抽象实现）</b>\n            <div>\n              <input type=\"button\" class=\"menu_button\" value=\"＋ 添加任务\" @click=\"addTask\" />\n              <input type=\"button\" class=\"menu_button\" value=\"恢复默认\" @click=\"resetTasks\" />\n            </div>\n          </div>\n          <div v-for=\"(task, index) in settings.tasks\" :key=\"task.id\" class=\"postgen-task\">\n            <div class=\"flex-container\">\n              <input :id=\"'postgen-task-enable-' + task.id\" v-model=\"task.enabled\" type=\"checkbox\" />\n              <label :for=\"'postgen-task-enable-' + task.id\">启用</label>\n              <input v-model=\"task.name\" type=\"text\" class=\"text_pole\" placeholder=\"任务名\" style=\"flex: 1\" />\n              <input v-model=\"task.tag\" type=\"text\" class=\"text_pole\" placeholder=\"标签\" style=\"width: 90px\" />\n            </div>\n            <div class=\"flex-container\">\n              <input v-model=\"task.sep\" type=\"text\" class=\"postgen-num\" placeholder=\"分隔符\" style=\"width: 90px\" />\n              <label class=\"postgen-label\">列表式分隔符（选项用「|」，可留空）</label>\n            </div>\n            <div class=\"flex-container\">\n              <input v-model.number=\"task.max_tokens\" type=\"number\" min=\"16\" max=\"4096\" class=\"postgen-num\" />\n              <label class=\"postgen-label\">max_tokens</label>\n              <input v-model.number=\"task.temperature\" type=\"number\" min=\"0\" max=\"2\" step=\"0.1\" class=\"postgen-num\" />\n              <label class=\"postgen-label\">温度</label>\n              <input type=\"button\" class=\"menu_button postgen-danger\" value=\"删除\" @click=\"removeTask(index)\" />\n            </div>\n            <textarea v-model=\"task.prompt\" class=\"postgen-prompt\" rows=\"4\" placeholder=\"任务提示词（告诉辅助 LLM 生成什么、什么格式）\"></textarea>\n          </div>\n        </div>\n\n        <div class=\"flex-container\">\n          <input type=\"button\" class=\"menu_button\" value=\"↻ 为最后一楼重新生成正文后续\" :disabled=\"rerunning\" @click=\"rerun\" />\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { storeToRefs } from 'pinia';\nimport { defaultTasks, useSettingsStore } from './settings';\nimport { apiSourceHint, fetchApiModels, testApiConnection } from './api';\nimport { processLatestAI } from './pipeline';\n\nconst store = useSettingsStore();\nconst { settings } = storeToRefs(store);\n\nconst apiKeyVisible = ref(false);\nconst fetching = ref(false);\nconst testing = ref(false);\nconst rerunning = ref(false);\nconst fetchedModels = ref<string[]>([]);\nconst apiTestStatus = ref('');\nconst apiTestOk = ref(false);\n\nconst apiHint = computed(() => apiSourceHint(settings.value.api));\n\nfunction addTask() {\n  const defaults = defaultTasks();\n  settings.value.tasks.push({\n    id: defaults[0].id,\n    name: '新任务',\n    tag: 'tag',\n    sep: '',\n    prompt: '',\n    max_tokens: 256,\n    temperature: 0.7,\n    enabled: true,\n  });\n}\n\nfunction removeTask(index: number) {\n  settings.value.tasks.splice(index, 1);\n}\n\nfunction resetTasks() {\n  settings.value.tasks = defaultTasks();\n}\n\nasync function fetchModels() {\n  if (!settings.value.api.apiurl.trim()) {\n    toastr.warning('请先填写 API 地址', '正文后续生成');\n    return;\n  }\n  fetching.value = true;\n  try {\n    const result = await fetchApiModels(settings.value.api);\n    fetchedModels.value = result.models;\n    toastr.success(`已拉取 ${result.models.length} 个模型（${result.via === 'tavern' ? '酒馆代拉取' : '浏览器直连'}）`, '正文后续生成');\n  } catch (error) {\n    toastr.warning('拉取失败：' + (error instanceof Error ? error.message : String(error)), '正文后续生成');\n  } finally {\n    fetching.value = false;\n  }\n}\n\nasync function testApi() {\n  testing.value = true;\n  apiTestStatus.value = '正在发送短请求…';\n  apiTestOk.value = false;\n  try {\n    const result = await testApiConnection(settings.value.api);\n    apiTestStatus.value = `连接成功 · ${result.source === 'claude' ? 'Anthropic' : 'OpenAI'} · 返回：${result.text}`;\n    apiTestOk.value = true;\n  } catch (error) {\n    apiTestStatus.value = '测试失败：' + (error instanceof Error ? error.message : String(error));\n    apiTestOk.value = false;\n  } finally {\n    testing.value = false;\n  }\n}\n\nasync function rerun() {\n  rerunning.value = true;\n  try {\n    await processLatestAI(true);\n  } finally {\n    rerunning.value = false;\n  }\n}\n</script>\n\n<style scoped>\n.postgen-settings {\n  --postgen-accent: #4ecdc4;\n  --postgen-danger: #f5576c;\n}\n\n.postgen-block {\n  margin-bottom: 10px;\n}\n\n.postgen-block > b {\n  display: block;\n  margin-bottom: 6px;\n}\n\n.postgen-block .flex-container {\n  margin-bottom: 5px;\n}\n\n.postgen-hint {\n  display: block;\n  margin-top: 3px;\n  color: #888;\n  font-size: 11px;\n}\n\n.postgen-ok {\n  color: var(--postgen-accent);\n}\n\n.postgen-warn {\n  color: #f0ad4e;\n}\n\n.postgen-num {\n  width: 70px;\n}\n\n.postgen-select {\n  max-width: 260px;\n}\n\n.postgen-model-select {\n  display: block;\n  width: 100%;\n  margin-bottom: 5px;\n}\n\n.postgen-label {\n  font-size: 12px;\n  color: #888;\n  margin-left: 6px;\n  white-space: nowrap;\n}\n\n.postgen-task {\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: 6px;\n  padding: 8px;\n  margin-bottom: 8px;\n  background: rgba(255, 255, 255, 0.03);\n}\n\n.postgen-prompt {\n  width: 100%;\n  box-sizing: border-box;\n  resize: vertical;\n  min-height: 60px;\n  font-family: inherit;\n  font-size: 12px;\n}\n\n.postgen-danger {\n  margin-left: auto;\n}\n</style>\n"],"sourceRoot":""}]);
