import type { PostGenSettings, TaskSettings } from './settings';
import { useSettingsStore } from './settings';
import { buildCustomApi, resolveApiSource, apiSourceLabel } from './api';

// ============ 工具 ============

function fingerprint(text: string): string {
  let h1 = 2166136261;
  let h2 = 5381;
  const s = String(text || '');
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 ^= c;
    h1 = Math.imul(h1, 16777619);
    h2 = Math.imul(h2, 33) ^ c;
  }
  return (h1 >>> 0).toString(36) + ':' + (h2 >>> 0).toString(36) + ':' + s.length;
}

function stripTaskTags(text: string, tasks: { tag: string }[]): string {
  let result = String(text || '');
  for (const task of tasks) {
    if (!task.tag) {
      continue;
    }
    const tag = _.escapeRegExp(task.tag);
    try {
      result = result.replace(new RegExp(`<${tag}>[\\s\\S]*?</${tag}>`, 'g'), '');
    } catch {
      // 非法标签正则, 忽略
    }
  }
  return result;
}

function extractTagContent(text: string, tag: string): string | null {
  if (!tag) {
    return null;
  }
  const match = String(text || '').match(new RegExp(`<${_.escapeRegExp(tag)}>([\\s\\S]*?)</${_.escapeRegExp(tag)}>`, 'i'));
  return match ? match[1].trim() : null;
}

function log(...args: unknown[]): void {
  console.info('[正文后续生成]', ...args);
}

function logError(...args: unknown[]): void {
  console.error('[正文后续生成]', ...args);
}

// ============ 状态 ============

const processed_versions = new Map<number, string>();
let session = 0;

export function resetPipelineState(): void {
  session++;
  processed_versions.clear();
}

function fingerprintSettings(settings: PostGenSettings): string {
  return fingerprint(
    JSON.stringify({
      api: settings.api,
      context: settings.context,
      timeout_seconds: settings.timeout_seconds,
      tasks: settings.tasks.map(t => ({ enabled: t.enabled, tag: t.tag, prompt: t.prompt, max_tokens: t.max_tokens, temperature: t.temperature })),
    }),
  );
}

// ============ 消息获取 ============

function getLatestAIMessage(): ChatMessage | null {
  try {
    const messages = getChatMessages('-1', { role: 'assistant' });
    return messages.length ? messages[0] : null;
  } catch (error) {
    logError('获取最新消息失败:', error);
    return null;
  }
}

function getRecentAIMessages(current_mid: number, count: number): ChatMessage[] {
  try {
    const all = getChatMessages('0-{{lastMessageId}}', { role: 'assistant' });
    return all.filter(m => m.message_id < current_mid).slice(-count);
  } catch (error) {
    logError('获取前情提要失败:', error);
    return [];
  }
}

function extractPreviousOutputs(recent_messages: ChatMessage[], tasks: TaskSettings[]): { tag: string; content: string }[] {
  const result: { tag: string; content: string }[] = [];
  const remaining = [...tasks];
  for (let i = recent_messages.length - 1; i >= 0 && remaining.length; i--) {
    const text = recent_messages[i].message;
    for (let j = remaining.length - 1; j >= 0; j--) {
      const content = extractTagContent(text, remaining[j].tag);
      if (content !== null) {
        result.push({ tag: remaining[j].tag, content });
        remaining.splice(j, 1);
      }
    }
  }
  return result;
}

// ============ 上下文组装 ============

function buildContext(settings: PostGenSettings, narrative: string, recent_messages: ChatMessage[]): string {
  const lines: string[] = ['【正文】', narrative.trim()];
  if (recent_messages.length) {
    lines.push('', `【前情提要】最近 ${recent_messages.length} 层 AI 消息（不含本次正文）`);
    for (const message of recent_messages) {
      lines.push('AI: ' + stripTaskTags(message.message, settings.tasks).trim());
    }
  }
  const previous = extractPreviousOutputs(recent_messages, settings.tasks.filter(t => t.enabled));
  if (previous.length) {
    lines.push('', '【上轮任务输出】');
    for (const item of previous) {
      lines.push(`<${item.tag}>: ${item.content}`);
    }
  }
  return lines.join('\n');
}

// ============ 任务生成 ============

async function runTask(task: TaskSettings, context: string, settings: PostGenSettings, message_id: number): Promise<string | null> {
  const gen_id = `postgen_${message_id}_${task.id}_${Date.now()}`;
  const config: GenerateRawConfig = {
    generation_id: gen_id,
    should_silence: true,
    max_chat_history: 0,
    ordered_prompts: [
      { role: 'system', content: task.prompt },
      { role: 'user', content: context },
    ],
  };
  if (settings.api.apiurl.trim() || settings.api.model.trim()) {
    config.custom_api = buildCustomApi(settings.api, { max_tokens: task.max_tokens, temperature: task.temperature });
  }
  let timer: number | undefined;
  try {
    const timeout = new Promise<never>((_, reject) => {
      timer = window.setTimeout(() => {
        try {
          stopGenerationById(gen_id);
        } catch {
          // ignore
        }
        reject(new Error(`超时 ${settings.timeout_seconds} 秒`));
      }, settings.timeout_seconds * 1000);
    });
    const raw = await Promise.race([generateRaw(config), timeout]);
    if (typeof raw !== 'string' || !raw.trim()) {
      log(`任务「${task.name}」返回为空`);
      return null;
    }
    const tag = _.escapeRegExp(task.tag);
    const cleaned = raw
      .replace(new RegExp(`</?${tag}>`, 'gi'), '')
      .trim();
    if (!cleaned) {
      log(`任务「${task.name}」内容为空`);
      return null;
    }
    const result = `<${task.tag}>\n${cleaned}\n</${task.tag}>`;
    log(`任务「${task.name}」生成成功 (${cleaned.length}字)`);
    return result;
  } catch (error) {
    logError(`任务「${task.name}」生成失败:`, error instanceof Error ? error.message : error);
    return null;
  } finally {
    if (timer !== undefined) {
      clearTimeout(timer);
    }
  }
}

// ============ 主流程 ============

export async function processLatestAI(force = false): Promise<void> {
  const store = useSettingsStore();
  const settings = store.settings;
  if (!settings.enabled) {
    return;
  }
  const tasks = settings.tasks.filter(t => t.enabled && t.tag && t.prompt);
  if (!tasks.length) {
    toastr.info('没有启用任何生成任务', '正文后续生成');
    return;
  }
  const message = getLatestAIMessage();
  if (!message || !message.message.trim()) {
    log('没有找到可处理的 AI 消息');
    return;
  }
  const mid = message.message_id;
  const incoming = fingerprint(message.message);
  const current_session = session;
  if (!force && processed_versions.get(mid) === incoming) {
    return;
  }
  // 写回前置指纹, 防止消息事件造成重复处理
  processed_versions.set(mid, incoming);

  log(`处理 AI 消息 #${mid} (${message.message.length}字, ${tasks.length}个任务)`);
  const settings_fingerprint = fingerprintSettings(settings);
  const recent = getRecentAIMessages(mid, settings.context.ai_messages);
  const context = buildContext(settings, message.message, recent);
  const results = await Promise.allSettled(tasks.map(task => runTask(task, context, settings, mid)));
  if (current_session !== session) {
    log('会话已失效, 丢弃结果');
    return;
  }
  const outputs = results
    .map((result, index) => (result.status === 'fulfilled' ? result.value : null))
    .filter((output): output is string => !!output);

  if (!outputs.length) {
    log(`消息 #${mid} 所有任务均未生成, 保持原文`);
    return;
  }

  // 写回前再次确认楼层没有被其他操作修改 (如用户滑动重 roll)
  const now = getChatMessages(mid)[0];
  if (!now || fingerprint(now.message) !== incoming) {
    log(`消息 #${mid} 已被修改, 放弃写回`);
    return;
  }
  const stripped = stripTaskTags(now.message, settings.tasks).trimEnd();
  const appended = outputs.join('\n');
  const final_text = stripped ? stripped + '\n' + appended : appended;
  if (final_text === now.message) {
    return;
  }
  try {
    await setChatMessages([{ message_id: mid, message: final_text }], { refresh: 'affected' });
    processed_versions.set(mid, fingerprint(final_text));
    const summary = outputs
      .map(o => {
        const tag_match = o.match(/^<([^>]+)>/);
        return tag_match ? `〈${tag_match[1]}〉` : '任务';
      })
      .join(' ');
    const api_note = settings.api.apiurl.trim() ? ` / ${apiSourceLabel(resolveApiSource(settings.api))}` : '';
    log(`消息 #${mid} 已写回: ${summary}${api_note}`);
    toastr.success(`正文后续已写入 #${mid}: ${summary}`, '正文后续生成');
    if (settings_fingerprint !== fingerprintSettings(settings)) {
      log('设置在处理过程中发生变化, 已按新设置继续');
    }
  } catch (error) {
    processed_versions.delete(mid);
    logError(`消息 #${mid} 写回失败:`, error instanceof Error ? error.message : error);
    toastr.error('正文后续写回失败', '正文后续生成');
  }
}
