import type { ApiSettings } from './settings';

export function normalizeApiRoot(apiurl: string): string {
  const url = String(apiurl || '').trim().replace(/\/+$/, '');
  if (!url) {
    throw new Error('请先填写 API 地址');
  }
  const without_tail = url.replace(/\/(?:models|chat\/completions|responses|messages)$/i, '');
  const v1 = without_tail.match(/^(.*?\/v1)(?:\/.*)?$/i);
  if (v1) {
    return v1[1];
  }
  return without_tail + '/v1';
}

export function apiSourceLabel(source: string): string {
  return source === 'claude' ? 'Anthropic Messages' : 'OpenAI Chat Completions';
}

export function resolveApiSource(api: ApiSettings): string {
  const chosen = String(api.source || 'auto').toLowerCase();
  if (chosen === 'openai' || chosen === 'claude') {
    return chosen;
  }
  return 'openai';
}

export function apiSourceHint(api: ApiSettings): string {
  const source = resolveApiSource(api);
  return (api.source === 'auto' ? '自动识别：' : '手动指定：') + apiSourceLabel(source);
}

export function buildCustomApi(api: ApiSettings, extra: { max_tokens: number; temperature: number }): CustomApiConfig {
  const custom: CustomApiConfig = {};
  if (String(api.apiurl || '').trim()) {
    custom.apiurl = normalizeApiRoot(api.apiurl);
    custom.source = resolveApiSource(api);
  }
  if (String(api.apiKey || '').trim()) {
    custom.key = api.apiKey;
  }
  if (String(api.model || '').trim()) {
    custom.model = api.model;
  }
  custom.max_tokens = extra.max_tokens;
  custom.temperature = extra.temperature;
  return custom;
}

function normalizeModelList(source: unknown): string[] {
  const list = Array.isArray(source)
    ? source
    : source && Array.isArray((source as { data?: unknown }).data)
      ? (source as { data: unknown[] }).data
      : source && Array.isArray((source as { models?: unknown }).models)
        ? (source as { models: unknown[] }).models
        : [];
  const models = list
    .map(item => {
      if (typeof item === 'string') {
        return item;
      }
      if (item && typeof item === 'object') {
        const id = (item as { id?: unknown }).id;
        const name = (item as { name?: unknown }).name;
        return typeof id === 'string' ? id : typeof name === 'string' ? name : '';
      }
      return '';
    })
    .filter((x): x is string => !!x);
  return Array.from(new Set(models)).sort((a, b) => a.localeCompare(b));
}

export async function fetchApiModels(api: ApiSettings): Promise<{ models: string[]; via: string }> {
  const root = normalizeApiRoot(api.apiurl);
  const key = String(api.apiKey || '').trim();
  if (typeof getModelList === 'function') {
    try {
      const models = normalizeModelList(await getModelList({ apiurl: root, key: key || undefined }));
      if (models.length) {
        return { models, via: 'tavern' };
      }
    } catch {
      // 回退到浏览器直连
    }
  }
  const headers: Record<string, string> = {};
  if (key) {
    headers.Authorization = 'Bearer ' + key;
  }
  const response = await fetch(root + '/models', { method: 'GET', headers });
  if (!response.ok) {
    throw new Error('HTTP ' + response.status);
  }
  const models = normalizeModelList(await response.json());
  if (!models.length) {
    throw new Error('模型列表为空');
  }
  return { models, via: 'browser' };
}

export async function testApiConnection(api: ApiSettings): Promise<{ source: string; text: string }> {
  if (!String(api.apiurl || '').trim()) {
    throw new Error('请先填写 API 地址');
  }
  if (typeof generateRaw !== 'function') {
    throw new Error('generateRaw 不可用');
  }
  const source = resolveApiSource(api);
  const genId = 'postgen_test_' + Date.now();
  const config: GenerateRawConfig = {
    generation_id: genId,
    should_silence: true,
    max_chat_history: 0,
    ordered_prompts: [
      { role: 'system', content: '你是 API 连通性测试助手。直接给出答案，不要解释。' },
      { role: 'user', content: '只回复 OK' },
    ],
    custom_api: buildCustomApi(api, { max_tokens: 512, temperature: 0 }),
  };
  let timer: number | undefined;
  try {
    const timeout = new Promise<never>((_, reject) => {
      timer = window.setTimeout(() => {
        try {
          stopGenerationById(genId);
        } catch {
          // ignore
        }
        reject(new Error('连接测试超过 60 秒（协议：' + apiSourceLabel(source) + '）'));
      }, 60000);
    });
    const result = await Promise.race([generateRaw(config), timeout]);
    if (result === undefined || result === null || String(result).trim() === '') {
      throw new Error('接口返回为空');
    }
    return { source, text: String(result).trim().slice(0, 80) };
  } finally {
    if (timer !== undefined) {
      clearTimeout(timer);
    }
  }
}
